package org.eclipse.rdf4j.query.algebra.helpers;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.List;
import java.util.Set;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Bound;
import org.eclipse.rdf4j.query.algebra.Exists;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Filter.ConditionBindingScope;
import org.eclipse.rdf4j.query.algebra.Not;
import org.eclipse.rdf4j.query.algebra.Projection;
import org.eclipse.rdf4j.query.algebra.ProjectionElemList;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.ValueExpr;
import org.eclipse.rdf4j.query.algebra.Var;
import org.junit.jupiter.api.Test;

class ProjectionContextObservationTest {

	private static final String CALLER = "callerGraph";
	private static final String PRIVATE = "privateGraphInput";

	@Test
	void inheritedCallerGraphCannotDisappearFromExistsObservationProof() {
		Projection projection = projection(Var.of(CALLER));
		for (ValueExpr condition : List.of(new Exists(projection), new Not(new Exists(projection.clone())),
				new Exists(new Filter(new SingletonSet(), new Not(new Exists(projection.clone())))))) {
			TupleExprs.ConditionBindingDomain observed = TupleExprs.conditionBindingDomain(condition);
			assertThat(!observed.known() || observed.names().contains(CALLER))
					.as("the projection lowering reads its unbound callerGraph to supply the private graph input")
					.isTrue();
			assertThat(observed.names()).contains(PRIVATE);
			assertThat(TupleExprs.conditionFrameContainsAllObservations(observed, Set.of(PRIVATE))).isFalse();
		}
	}

	@Test
	void unvisitedContextVarSubclassCannotBorrowBuiltinCompleteness() {
		Var context = new Var(CALLER) {
		};
		TupleExprs.ConditionBindingDomain observed = TupleExprs.conditionBindingDomain(new Exists(projection(context)));
		assertThat(observed.known())
				.as("a metadata-held Var implementation needs the same exact-class proof as a visited Var")
				.isFalse();
		assertThat(TupleExprs.conditionFrameContainsAllObservations(observed, Set.of(CALLER, PRIVATE))).isFalse();
	}

	@Test
	void ordinaryProjectionWithoutCallerMetadataKeepsItsCompleteDomain() {
		Projection projection = projection(null);
		projection.setInheritedGraphParameter(null);
		TupleExprs.ConditionBindingDomain observed = TupleExprs.conditionBindingDomain(new Exists(projection));
		assertThat(observed.known()).isTrue();
		assertThat(observed.names()).containsExactly(PRIVATE);
		assertThat(TupleExprs.conditionFrameContainsAllObservations(observed, Set.of(PRIVATE))).isTrue();
	}

	@Test
	void fixedCallerGraphDoesNotBecomeAnOrdinaryBindingRead() {
		Projection projection = projection(
				Var.of("constantGraphSymbol", SimpleValueFactory.getInstance().createIRI("urn:graph:fixed")));
		TupleExprs.ConditionBindingDomain observed = TupleExprs.conditionBindingDomain(new Exists(projection));
		assertThat(observed.names()).contains(PRIVATE).doesNotContain("constantGraphSymbol");
	}

	private static Projection projection(Var context) {
		Filter body = new Filter(new SingletonSet(), new Bound(Var.of(PRIVATE)));
		body.setConditionBindingScope(ConditionBindingScope.ALL);
		Projection projection = new Projection(body, new ProjectionElemList(), true);
		projection.setProjectionContext(context);
		projection.setInheritedGraphParameter(PRIVATE);
		return projection;
	}
}
